// Keep the screen on. A web page gets no GPS while the iPhone is locked, so this matters.
// Uses the Screen Wake Lock API (Safari 16.4+) and falls back to NoSleep's silent video.
// Home Screen web apps before iOS 18.4 accepted a wake lock without honouring it, so in
// that mode (only) the silent looping video also runs, belt and braces. On iOS 18.4+ the
// video is not played: decoding it all race long would cost battery for nothing.

// Home Screen app on an iOS older than 18.4?
function oldStandaloneIos() {
  if (typeof navigator === 'undefined' || navigator.standalone !== true) return false;
  const m = /OS (\d+)_(\d+)/.exec(navigator.userAgent || '');
  if (!m) return true;
  const major = Number(m[1]), minor = Number(m[2]);
  return major < 18 || (major === 18 && minor < 4);
}

export class Wake {
  constructor() {
    this.wanted = false;
    this.lock = null;
    this.video = null;
    this.method = null;
    document.addEventListener('visibilitychange', () => {
      if (document.visibilityState === 'visible' && this.wanted) this.enable();
    });
  }

  get active() { return !!(this.lock && !this.lock.released) || this.method === 'video'; }

  // Call from a user gesture the first time.
  async enable() {
    this.wanted = true;
    if (oldStandaloneIos()) this._video();
    if ('wakeLock' in navigator) {
      try {
        if (!this.lock || this.lock.released) {
          this.lock = await navigator.wakeLock.request('screen');
          this.lock.addEventListener('release', () => { if (this.method === 'wakelock') this.method = null; });
        }
        this.method = 'wakelock';
        return this.method;
      } catch { /* fall through to the video trick */ }
    }
    if (this._video()) { this.method = 'video'; return this.method; }
    try {
      if (!this.video && window.NoSleep) this.video = new window.NoSleep();
      if (this.video) {
        await this.video.enable();
        this.method = 'video';
      }
    } catch { this.method = null; }
    return this.method;
  }

  // A tiny silent looping video (from NoSleep.js) keeps iOS awake while it plays.
  _video() {
    try {
      if (!this.vid) {
        const v = document.createElement('video');
        v.setAttribute('playsinline', '');
        v.setAttribute('muted', '');
        v.muted = true;
        v.loop = true;
        v.setAttribute('title', 'keep awake');
        v.style.cssText = 'position:fixed;left:0;top:0;width:1px;height:1px;opacity:0.01;pointer-events:none;';
        v.src = SILENT_MP4;
        document.body.appendChild(v);
        this.vid = v;
      }
      const p = this.vid.play();
      if (p && p.catch) p.catch(() => {});
      return true;
    } catch { return false; }
  }

  disable() {
    this.wanted = false;
    try { if (this.vid) this.vid.pause(); } catch { /* ignore */ }
    try { if (this.lock) this.lock.release(); } catch { /* ignore */ }
    try { if (this.video) this.video.disable(); } catch { /* ignore */ }
    this.lock = null;
    this.method = null;
  }
}

const SILENT_MP4 = 'data:video/mp4;base64,';
